export async function searchPhotos(query: string, perPage = 5): Promise<PexelsPhoto[]> {
  try {
    const res = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(query)}&per_page=${perPage}&orientation=landscape`, {
      headers: { Authorization: process.env.PEXELS_API_KEY! }
    });
    if (!res.ok) return [];
    const data = await res.json();
    return data.photos.map((p: any) => ({ url: p.src.large, alt: p.alt || query, photographer: p.photographer }));
  } catch { return []; }
}
